setcpm(96/4)

// The refrain makes seeded choices, so its variants A' and A'' ornament it differently
const refrain = n("<[0 2 4 2] [5 4 2 0] [1 3 5 3] [4@2 2 0]>")
  .sometimesBy(.3, x => x.add(2)).degradeBy(.1)
  .scale("G:major").transpose(12)
  .s("triangle").timbre("bright").decay(.25).sustain(.3).release(.2)

// Two episodes: one in the relative minor, one in C
const episode1 = n("<[4 ~ 5 4] [2@2 0@2] [3 ~ 4 3] [1@4]>").scale("E:minor").transpose(12)
  .s("sine").timbre("hollow").vib(5).vibdepth(.1).attack(.05).sustain(.6).release(.4)
const episode2 = n("<[0 4 7 4] [5 4 2 4] [0 4 7 9] [7@4]>").scale("C:major").transpose(12)
  .s("sawtooth").timbre("reed").lpf(2400).attack(.03).sustain(.5).release(.2)

// form: A is the first part, B the second, C the third; @4 makes each section four bars
// Every section starts its part from its own first bar
melody: form("A@4 B@4 A'@4 C@4 A''@4", refrain, episode1, episode2).room(.4).gain(.24)

// The bass follows the same layout, without variants
bass: form("A@4 B@4 A@4 C@4 A@4", note("<g2 c3 d3 g2>"), note("<e2 c2 a1 b1>"), note("<c2 f2 c2 g2>"))
  .s("sawtooth").lpf(700).attack(.02).decay(.3).sustain(.5).release(.2).gain(.3)

drums: s("bd ~ bd ~, ~ rim ~ rim, hh*8").gain(.32)

setcpm(84/4)

// One arc over 32 bars: soft, a long rise, a dip, a second peak, then nothing
const arc = env("0.1 1@5 0.4 0.9@2 0", 32)

// The pad's filter and level both follow the arc
pad: note("<[d3,f3,a3] [bb2,d3,f3] [g2,bb2,d3] [a2,c#3,e3]>").slow(2)
  .s("sawtooth").unison(3).detune(.2).attack(1).release(2)
  .lpf(arc.range(300, 2600)).room(.6).gain(arc.range(.04, .18))

// fadein raises the strings from silence over the first eight bars
strings: note("<d2 bb1 g1 a1>").slow(2).s("sawtooth").lpf(600)
  .attack(.3).sustain(.7).release(.8).gain(.24).fadein(8)

// enter and exit: the hats play bars 4 to 27, the kick bars 8 to 23
hats: s("hh*16").hpf(7000).gain(arc.range(.05, .28)).enter(4).exit(28)
kick: s("bd*4").shape(.2).gain(.7).enter(8).exit(24)

// during: from bar 16 to bar 23 the melody runs twice as fast
melody: n("<[0 ~ 2 4] [3 ~ 2 ~] [1 ~ 0 ~] [4@2 3 2]>").scale("D:minor").transpose(12)
  .during(16, 24, x => x.fast(2))
  .s("triangle").timbre("soft").decay(.5).sustain(.1).release(.6).room(.5).gain(.22)

// fadeout lowers the bells over eight bars from bar 24
bells: note("<a5 ~ f5 ~ d5 ~ e5 ~>").s("sine").fm(3).fmh(2.76)
  .decay(2).sustain(0).release(2).space("hall").gain(.12).fadeout(8, 24)

setcpm(84/4)

// The subject, written as scale degrees so every transformation stays in the key
const subject = n("<[0 2 4 3] [1 2 0 -1]>")
const voiced = (x) => x.scale("D:minor").transpose(12)
  .s("sawtooth").vib(5).vibdepth(.1).lpf(2600).attack(.03).sustain(.6).release(.2)

// Five sections of four bars:
// A the subject, B inverted around degree 2, C each two-bar window backwards,
// D raised one degree more each bar for four bars, E the opening half of each bar repeated
lead: form("A@4 B@4 C@4 D@4 E@4",
  subject, subject.invert(2), subject.retro(2), subject.sequence(1, 4), subject.fragment(.5))
  .voiced().room(.4).gain(.2)

// augment: the bass plays the same subject four times slower, an octave down
bass: subject.augment(4).scale("D:minor").octave(-1)
  .s("sawtooth").lpf(700).attack(.1).sustain(.7).release(.5).room(.4).gain(.26)

drone: note("[d2,a2]").slow(4).s("sine").attack(2).sustain(1).release(3).gain(.14)
click: s("rim ~ rim ~").gain(.12)

setcpm(72/4)

// One tune; every strong beat lands on D, F# or A, so the entries fit together
const tune = n("<[0 2 4 2] [4 5 4 2] [7 6 7 4] [2@2 1 0]>")

// canon: three copies, each one bar later and seven degrees (an octave) higher
round: tune.canon(3, 1, 7).scale("D:major")
  .s("sawtooth").vib(5.5).vibdepth(.1).attack(.04).sustain(.6).release(.25)
  .lpf(2600).room(.4).gain(.15)

// prolation: the same tune at half speed and quarter speed at once, an octave down
cello: tune.prolation(1/2, 1/4).scale("D:major").octave(-1)
  .s("sawtooth").lpf(700).attack(.08).sustain(.6).release(.4).room(.4).gain(.18)

// A harpsichord marks the off-beats
harpsichord: note("[d4,f#4,a4]").struct("~ x ~ x").s("square").pw(.15)
  .decay(.15).sustain(0).lpf(3000).gain(.07)

setcpm(100/4)

// One twelve-note figure for both pianos
const figure = note("e4 f#4 b4 c#5 d5 f#4 e4 c#5 b4 f#4 d5 c#5")
const keys = (x) => x.s("triangle").timbre("bright").attack(.002).decay(.2).sustain(0).release(.2)

// The first piano holds still
still: figure.keys().pan(.25).gain(.24)

// phase delays bar c by c twelfths of a bar, wrapped within the bar:
// the second piano slips one note each bar and meets the first again every twelve
drift: figure.phase(1/12).keys().pan(.75).gain(.24)

// A marimba keeps the low notes
marimba: note("b2 ~ e3 ~ f#3 ~").s("sine").fm(.6).fmh(4).decay(.35).sustain(0).room(.3).gain(.26)

setcpm(90/4)

// converge stacks copies at the given speed ratios, aligned so that at bar 8 they all start the figure together
// With 1, 9/8 and 5/4 they meet again every eight bars
clocks: n("0 2 4 7 4 2 0 -3").scale("A:minor pentatonic").transpose(12)
  .converge(8, 1, 9/8, 5/4)
  .s("triangle").timbre("glass").decay(.2).sustain(0).release(.3).room(.5).gain(.14)

// A bell marks every meeting point
bell: note("<a5 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(3).sustain(0).release(3).space("hall").gain(.14)

// The clock that keeps the steady tempo
tick: s("tick*4").gain(.1)
pad: note("[a2,e3,c4]").slow(8).s("sawtooth").unison(3).detune(.2)
  .attack(3).release(4).lpf(900).room(.7).gain(.1)

setcpm(90/4)

// Nørgård's infinity series: self-similar and never repeating, eight degrees per bar
// The van der Corput sequence spreads the notes evenly across the stereo field
melody: n(ints("norgard", 8)).scale("E:dorian").transpose(12)
  .s("triangle").timbre("glass").decay(.3).sustain(0).release(.5)
  .pan(ints("vdc", 8)).delay(.3).delaytime(3/16).room(.5).gain(.2)

// The ruler sequence counts how often 2 divides each step number: a binary hierarchy of accents
hats: s("hh*8").hpf(7000).gain(ints("ruler", 8).mod(4).mul(.08).add(.08))

// Thue-Morse: a rhythm that never repeats any block three times in a row
rims: s("rim*16").mask(ints("thuemorse", 16)).gain(.16)

// Fibonacci numbers modulo 5, read as pentatonic degrees: the pattern repeats every ten bars
bells: n(ints("fib", 2, 5)).scale("E:minor pentatonic").transpose(24)
  .s("sine").fm(2).fmh(2.76).decay(1).sustain(0).release(1.2).space("hall").gain(.1)

// The bass counts the Collatz steps from each bar number down to 1, folded into five degrees
bass: n(ints("collatz", 1).mod(5)).scale("E:minor pentatonic").octave(-1)
  .s("sawtooth").lpf(700).attack(.05).sustain(.7).release(.4).gain(.28)

kick: s("bd ~ ~ bd ~ ~ bd ~").lpf(300).gain(.45)

setcpm(124/4)

// sieve builds a rhythm from residue classes: m@r keeps the steps whose remainder modulo m is r
kick: s("bd").struct(sieve("4@0", 16)).shape(.2).gain(.75)
clap: s("cp").struct(sieve("8@4", 16)).room(.2).gain(.4)

// | joins, & keeps the overlap and - takes the complement
hats: s("hh").struct(sieve("(2@1 | 3@0) & -8@4", 16)).hpf(7000).gain(.24)

// Steps count from the start of the piece, so moduli that do not divide 16 drift across bars
rim: s("rim").struct(sieve("5@0 | 7@3", 16)).gain(.22)

// A Sturmian rhythm: five hits spread as evenly as possible over every thirteen steps
toms: s("lt").struct(ints("sturm", 16, 5, 13)).gain(.3)

// Clicks on the prime-numbered steps, growing sparser as the piece goes on
clicks: s("click").struct(ints("prime", 16)).hpf(3000).gain(.12)

// The bass reads the digits of 0, 1, 2, 3 ... written one after another in base 5
bass: n(ints("digits", 8, 5)).scale("C:minor").octave(-1)
  .s("sawtooth").lpf(800).lpq(4).decay(.15).sustain(.3).release(.05).gain(.38)

setcpm(96/4)

// lsys rewrites its symbols generation by generation, then spreads the result over some bars
// 0 becomes 0 2, 2 becomes 4, 4 becomes 0 4: after six generations, 28 notes over eight bars
melody: n(lsys("0", "0=0 2, 2=4, 4=0 4", 6, 8)).scale("A:minor").transpose(12)
  .s("triangle").timbre("soft").attack(.005).decay(.6).sustain(.1).release(.8)
  .room(.5).gain(.24)

// Sound names rewrite too: bd becomes bd hh, hh becomes sd bd; 20 hits over four bars
drums: s(lsys("bd", "bd=bd hh, hh=sd bd", 5, 4)).gain(.4)

// The Fibonacci word: 1 becomes 1 0, 0 becomes 1; after eight generations, 55 steps over four bars
rims: s("rim").struct(lsys("1", "1=1 0, 0=1", 8, 4)).hpf(1500).gain(.2)

bass: note("<a1 a1 f1 g1>").s("sine").attack(.1).sustain(.8).release(.6).gain(.32)
pad: note("<[a2,e3,c4] [f2,c3,a3]>").slow(4).s("sawtooth").unison(3).detune(.2)
  .attack(2).release(3).lpf(1000).room(.7).gain(.1)

setcpm(60/4)

// A row: every pitch class once, as numbers from 0 (C) to 11 (B)
const series = row("0 11 3 4 8 7 9 5 6 1 2 10")

// rowform: P plays the row, I inverts it, R reverses it, RI does both; the number transposes
upper: series.rowform("<P0 I5 R3 RI7>").slow(2).scale("C:chromatic").transpose(12)
  .s("sine").fm(1.5).fmh(2).attack(.01).decay(.5).sustain(.2).release(.6)
  .room(.5).gain(.22)

// The lower voice plays the retrograde inversion and a transposed prime, four bars each
lower: series.rowform("<RI0 P7>").slow(4).scale("C:chromatic").octave(-1)
  .s("sawtooth").lpf(900).attack(.1).sustain(.6).release(.6).room(.5).gain(.18)

// A quiet pulse keeps the bars
pulse: s("rim ~ ~ ~").room(.4).gain(.12)

setcpm(90/4)

// Six bells in rounds, highest first; ring cuts each bar into six and plays row c of plain hunt
// The rows come back to rounds every twelve bars
bells: note("c5 a4 g4 f4 d4 c4").ring("plainhunt", 6)
  .s("sine").fm(2).fmh(2.76).decay(1.2).sustain(0).release(1.5).space("church").gain(.2)

// permute plays four notes in the k-th of their 24 orderings, a different k each bar
chime: n("0 2 4 7").permute(4, "<0 5 11 17 23 6>").scale("F:major").transpose(12)
  .s("triangle").timbre("glass").decay(.4).sustain(0).release(.8)
  .delay(.3).delaytime(3/8).room(.5).gain(.12)

// An organ pedal under the tower
pedal: note("[f2,c3]").slow(4).s("sawtooth").timbre("organ").lpf(500)
  .attack(1).sustain(.8).release(2).space("church").gain(.14)

setcpm(104/4)

// The motif thins itself a little at random, so the variant A' differs from A
const motif = n("<[0 2 4 2] [3 2 1 ~] [4 5 6 4] [7@4]>").degradeBy(.1)

// .once() plays the form a single time: eight bars of the motif, eight of its inversion
// climbing in sequence, four of the variant, then silence
lead: form("A@8 B@8 A'@4", motif, motif.invert(4).sequence(1, 4)).once()
  .scale("C:major").transpose(12)
  .s("sawtooth").timbre("bright").lpf(2800).attack(.02).sustain(.6).release(.2)
  .room(.4).gain(.22)

bass: form("A@8 B@8 A@4", note("<c2 f2 g2 c2>"), note("<a1 e2 f2 g2>")).once()
  .s("sawtooth").lpf(700).attack(.02).decay(.3).sustain(.5).release(.2).gain(.3)

// The drums have their own twenty-bar form: grooves, fills and a crash on the last bar
const groove = s("bd ~ [~ bd] ~, ~ sd ~ sd, hh*8?0.2")
const fill = s("[lt lt mt mt] [ht ht ht ht]")
drums: form("A@6 B@2 A@6 B@2 A'@3 C", groove, fill, s("[bd,cr] ~ ~ ~")).once().gain(.5)

// The pad fades out over the last four bars
pad: note("<[c3,e3,g3] [f3,a3,c4] [g3,b3,d4] [c3,e3,g3]>").s("sawtooth").unison(3).detune(.2)
  .attack(.5).release(1.5).lpf(1500).room(.6).gain(.12).fadeout(4, 16)
